SourceCode.Declaration:
/// <summary>
/// Document Handler to unlock orders.
/// </summary>
[TFMDocumentType(staticMethodStr(TFMConstants, UnlockOrder))]
public class TFMUnlockOrder extends TFMDocumentHandler
{
    TFMOrderTypes         type;
    Str         backendId;
    Num         backendNum;
    Str         backendType;

}

Method.Source:
public TFMDocumentContentSubject getDocumentContentSubject()
{
    TFMDocumentContentSubject ret;    
    ret = strFmt('%1 %2 (%3)', type, backendNum, backendType);    
    return ret;
}

public void process()
{
    TFMLockedOrders         TFMLockedOrders;
    TFMBackendIDInstance    backendInstance;
    backendId = request.getFieldValue('BackendId');
    backendInstance = TFMBackendIDInstance::Construct(backendId);
    backendNum = backendInstance.parmFieldValue();
    backendType = backendInstance.parmType();
    if (backendId)
    {

        TFMLockedOrders = TFMLockedOrders::find(backendId, type);
        if(TFMLockedOrders)
        {
            // Delete
            TFMLockedOrders = TFMLockedOrders::find(backendId, type,true);
            TFMLockedOrders.delete();
            resultStr = "@TFM:MEL9";
        }
        else
        {
            // None (not found)
            throw error(strfmt("@TFM:MEL10",backendId, type));
        }
    }
    else
    {
        throw error(strfmt("@TFM:MEL11", TFMConstants::BackendID(), TFMConstants::Type()));
    }

}
